-- Count fans that appear in interactions (which link to support)
SELECT COUNT(DISTINCT i.interact_fan_pivot) as fan_count 
FROM interactions i;

-- Check engagement columns that could map to interaction consistency and platform stability
SELECT engage_reg, eng_rate, act_freq, avg_sess_count, session_productivity, soc_int_score 
FROM engagement LIMIT 5;

